const payload = $json.body ?? $json;
const text = `${payload.serviceType ?? ''} ${payload.problemDescription ?? ''} ${payload.urgencyNotes ?? ''}`.toLowerCase();

const gasTerms = ['gas smell', 'smell gas', 'smells like gas', 'gas leak'];
const safetyTerms = [...gasTerms, 'sewage backup', 'sewage backing up', 'raw sewage', 'sewage', 'major flooding', 'flooding', 'water pouring through'];
const emergencyTerms = ['burst pipe', 'pipe burst', 'no water', 'water heater failed', 'water heater leaking', 'water heater burst', 'no hot water at all'];
const highTerms = ['active leak', 'leaking', 'partial outage', 'only one bathroom', 'low pressure everywhere'];
const quoteTerms = ['repipe', 'water heater replacement', 'replace the water heater', 'tankless', 'sewer line', 'fixture', 'estimate', 'quote'];

const hit = (terms) => terms.some((term) => text.includes(term));

let tier;
if (hit(safetyTerms)) tier = 'safety-emergency';
else if (hit(emergencyTerms)) tier = 'emergency';
else if (hit(highTerms)) tier = 'high';
else if (hit(quoteTerms)) tier = 'quote';
else tier = 'routine';

const safetyEmergency = tier === 'safety-emergency';
const gasInvolved = hit(gasTerms);

const routingByTier = {
  'safety-emergency': 'immediate-human',
  emergency: 'immediate-human-callback',
  high: 'fast-callback',
  quote: 'stage-2-follow-up',
  routine: 'scheduled-nurture'
};

let nextAction;
if (safetyEmergency) {
  nextAction = gasInvolved
    ? 'Escalate to on-call human now. Voice script has already told the caller to leave the area and call the gas utility, or 911 if anyone is in danger. Never queue.'
    : 'Escalate to on-call human now. AI never holds sewage or flooding calls. Never queue.';
} else if (tier === 'emergency') {
  nextAction = 'Create immediate human callback task.';
} else if (tier === 'high') {
  nextAction = 'Create fast callback task, prioritized in the queue.';
} else if (tier === 'quote') {
  nextAction = 'Create estimate record for Stage 2 follow-up.';
} else {
  nextAction = 'Add to scheduled service and nurture queue.';
}

return [{
  json: {
    leadId: `DEMO-PLB-${Date.now()}`,
    tier,
    safetyEmergency,
    gasInvolved,
    routing: routingByTier[tier],
    voiceAgent: 'plumbing-bayou-city-intake',
    nextAction,
    lead: payload
  }
}];
